// === Tab: mySketch ===
// 雲のあれをやってみようかと。
// こんな感じになりますね。相似拡大。
// 絵文字でもいけそうね

let myShader;
const vs =
`
attribute vec3 aPosition;
varying vec2 vUv;
void main(){
  vUv = aPosition.xy * 2.0; // 今回は±1～±1で。
  gl_Position = vec4(aPosition * 2.0, 1.0);
}
`;

const fs =
`
precision mediump float;
varying vec2 vUv;
uniform float uTime;
uniform sampler2D uCloud;
uniform sampler2D uImg;

// hsb2rgb.
vec3 hsb2rgb(float h, float s, float b){
  vec3 c = vec3(h, s, b);
  vec3 rgb = clamp(abs(mod(c.x * 6.0 + vec3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0);
  rgb = rgb * rgb * (3.0 - 2.0 * rgb);
  return c.z * mix(vec3(1.0), rgb, c.y);
}

void main(){
  float y = length(vUv);
  y=pow(y, 0.25); // ここをいじるとおかしくなる。
  float x = (atan(vUv.y, vUv.x) + 3.14159) / 6.28318;

  y -= uTime*0.1;
  x += uTime*0.03;

	vec2 q = vec2(fract(2.0*x), fract(2.0*y));
	vec2 q1 = fract(q*3.0);

	// 半分暗くする処理
	// 境界線の両側に0と1を配する
	float factor;
	if(q1.x > q1.y){ factor = (q1.x-q1.y); }
	else{ factor = 1.0-(q1.y-q1.x); }

  vec4 col = texture2D(uCloud, q);
	vec4 fox = texture2D(uImg, q);

  float c = length(vUv);
	// ここもオーバーレイにする？それともソフトライトにする？
	vec3 src = hsb2rgb(fract(uTime*0.1), c, pow(c, 0.25));
  float gs = (col.r + col.g + col.b) / 3.0;
	if(gs < 0.5){
	  col.rgb = 2.0 * col.rgb * src;
	}else{
	  col.rgb = 2.0 * (col.rgb + src - col.rgb * src) - 1.0;
	}
	col.rgb *= vec3(factor*0.5, factor*0.75, factor);

	// 中心付近を暗くする処理
  col.a *= pow(length(vUv), 0.5);
  fox.a *= pow(length(vUv), 0.5);

	// アルファブレンディング
	col.rgb = col.rgb * (1.0-fox.a) + fox.rgb * fox.a;
	col.a = col.a + fox.a - col.a * fox.a;

  gl_FragColor = col * vec4(vec3(col.a), 1.0);
}
`;

let cloudImg;
let img;
function preload(){
  cloudImg = loadImage("https://upload.wikimedia.org/wikipedia/commons/0/07/Tornado3_-_NOAA.jpg");
}

function setup() {
  createCanvas(920, 690, WEBGL);
  shader(myShader = createShader(vs, fs));
  pixelDensity(1);
	img = createGraphics(width, width*.75);
	img.textSize(96);
	img.textAlign(CENTER, CENTER);
}

function draw() {
	const uTime = millis()/1000;
  background(0);
	img.clear();
	for(let i=1; i<8; i++){
		img.text("❤️", 96 + (1536*noise(i)%784), i*96);
	}
	img.text("❤️", 480, 0);
	img.text("❤️", 480, 768);
  myShader.setUniform("uTime", uTime);
  myShader.setUniform("uCloud", cloudImg);
	myShader.setUniform("uImg", img);
  plane(0);
}

let lapse = 0;    // mouse timer
function mousePressed(){
// prevents mouse press from registering twice
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() +      ".jpg");
    lapse = millis();
  }
}

